a<-commandArgs(TRUE);repo<-normalizePath(if(length(a))a[1] else '.',winslash='/')
source(file.path(repo,'methodology/contracts.R'));source(file.path(repo,'methodology/tools.R'));source(file.path(repo,'acceptance/acc003/sql_test.R'));source(file.path(repo,'acceptance/acc003/pretest.R'))
d<-wf_read(file.path(repo,'templates/design.json'));p<-tempfile('checker-pretest-',tmpdir=if(nzchar(Sys.getenv('WF_TEST_EVIDENCE'))) Sys.getenv('WF_TEST_EVIDENCE') else tempdir());r<-wf_pretest(repo,d,p)
stopifnot(r$status=='PASS',setequal(unlist(r$passed_cases),wf_pretest_case_ids()))
cat('Checker pretest:',length(r$passed_cases),'/',length(wf_pretest_case_ids()),'passed\nEvidence:',p,'\n')
